  "passport.noSharesYet": { ar:"لم تنشئ روابط مشاركة بعد.", en:"You haven't created any share links yet.", tr:"Henüz paylaşım bağlantısı oluşturmadınız.", zh:"你还没有创建任何分享链接。", hi:"आपने अभी तक कोई साझाकरण लिंक नहीं बनाया है।", es:"Aún no has creado ningún enlace para compartir.", fr:"Vous n'avez pas encore créé de lien de partage.", ur:"آپ نے ابھی تک کوئی اشتراک لنک نہیں بنایا۔" },

  "upload.errFileTooLarge": { ar:"حجم الملف أكبر من 20MB في الإعداد الحالي.", en:"File size exceeds 20MB in the current setup.", tr:"Dosya boyutu mevcut ayarda 20MB'ı aşıyor.", zh:"文件大小超过当前配置的 20MB。", hi:"फ़ाइल का आकार वर्तमान सेटअप में 20MB से अधिक है।", es:"El tamaño del archivo supera los 20MB en la configuración actual.", fr:"La taille du fichier dépasse 20 Mo dans la configuration actuelle.", ur:"فائل کا حجم موجودہ سیٹ اپ میں 20MB سے زیادہ ہے۔" },
  "upload.errCompileFailed": { ar:"تعذر تحليل التكليف", en:"Could not analyze the assignment", tr:"Ödev analiz edilemedi", zh:"无法解析该作业", hi:"असाइनमेंट का विश्लेषण नहीं किया जा सका", es:"No se pudo analizar la tarea", fr:"Impossible d'analyser le devoir", ur:"اسائنمنٹ کا تجزیہ نہیں ہو سکا" },
  "upload.errClipboard": { ar:"لم يسمح المتصفح بقراءة الحافظة. استخدم اللصق داخل الحقل.", en:"The browser blocked clipboard access. Paste directly into the field.", tr:"Tarayıcı pano erişimini engelledi. Doğrudan alana yapıştırın.", zh:"浏览器阻止了剪贴板访问。请直接粘贴到输入框中。", hi:"ब्राउज़र ने क्लिपबोर्ड एक्सेस रोक दिया। सीधे फ़ील्ड में पेस्ट करें।", es:"El navegador bloqueó el portapapeles. Pega directamente en el campo.", fr:"Le navigateur a bloqué le presse-papiers. Collez directement dans le champ.", ur:"براؤزر نے کلپ بورڈ روک دیا۔ براہِ راست خانے میں پیسٹ کریں۔" },
  "upload.errDictationUnsupported": { ar:"الإملاء الصوتي غير مدعوم في هذا المتصفح.", en:"Voice dictation is not supported in this browser.", tr:"Sesli dikte bu tarayıcıda desteklenmiyor.", zh:"此浏览器不支持语音听写。", hi:"इस ब्राउज़र में वॉइस डिक्टेशन समर्थित नहीं है।", es:"El dictado por voz no es compatible con este navegador.", fr:"La dictée vocale n'est pas prise en charge dans ce navigateur.", ur:"اس براؤزر میں صوتی ڈکٹیشن معاون نہیں ہے۔" },
  "upload.errMicCapture": { ar:"تعذر التقاط الصوت. تحقق من إذن الميكروفون.", en:"Could not capture audio. Check microphone permission.", tr:"Ses yakalanamadı. Mikrofon iznini kontrol edin.", zh:"无法捕获音频。请检查麦克风权限。", hi:"ऑडियो कैप्चर नहीं किया जा सका। माइक्रोफ़ोन अनुमति जांचें।", es:"No se pudo capturar el audio. Verifica el permiso del micrófono.", fr:"Impossible de capturer l'audio. Vérifiez l'autorisation du microphone.", ur:"آڈیو کیپچر نہیں ہو سکا۔ مائیکروفون کی اجازت چیک کریں۔" },
  "upload.summaryRequirements": { ar:"{n} متطلب", en:"{n} requirements", tr:"{n} gereksinim", zh:"{n} 项要求", hi:"{n} आवश्यकताएँ", es:"{n} requisitos", fr:"{n} exigences", ur:"{n} تقاضے" },
