  "upload.whatUnderstood": { ar:"ماذا فهم النظام؟", en:"What did the system understand?", tr:"Sistem neyi anladı?", zh:"系统理解了什么？", hi:"सिस्टम ने क्या समझा?", es:"¿Qué entendió el sistema?", fr:"Qu'a compris le système ?", ur:"سسٹم نے کیا سمجھا؟" },
