  "upload.confidenceLabel": { ar:"ثقة {n}%", en:"confidence {n}%", tr:"güven {n}%", zh:"置信度 {n}%", hi:"विश्वास {n}%", es:"confianza {n}%", fr:"confiance {n}%", ur:"اعتماد {n}%" },
