  "settings.languageNote": { ar:"اختر لغة الواجهة؛ يتبدّل الاتجاه RTL/LTR تلقائيًا ويُحفظ اختيارك.", en:"Choose the interface language; RTL/LTR direction switches automatically and your choice is saved.", tr:"Arayüz dilini seçin; RTL/LTR yönü otomatik değişir ve seçiminiz kaydedilir.", zh:"选择界面语言；RTL/LTR 方向自动切换并保存您的选择。", hi:"इंटरफ़ेस भाषा चुनें; RTL/LTR दिशा स्वतः बदलती है और आपका चयन सहेजा जाता है।", es:"Elige el idioma de la interfaz; la dirección RTL/LTR cambia automáticamente y se guarda tu elección.", fr:"Choisissez la langue de l'interface ; la direction RTL/LTR change automatiquement et votre choix est enregistré.", ur:"انٹرفیس کی زبان منتخب کریں؛ RTL/LTR سمت خودبخود بدلتی ہے اور آپ کا انتخاب محفوظ ہوتا ہے۔" },
  "settings.academicProfile": { ar:"الملف الأكاديمي", en:"Academic profile", tr:"Akademik profil", zh:"学术资料", hi:"शैक्षणिक प्रोफ़ाइल", es:"Perfil académico", fr:"Profil académique", ur:"تعلیمی پروفائل" },
  "settings.profilePlaceholder": { ar:"يمكنك إضافة الجامعة والتخصص والفصل.", en:"You can add your university, specialization, and term.", tr:"Üniversite, uzmanlık ve dönem ekleyebilirsiniz.", zh:"您可以添加大学、专业和学期。", hi:"आप विश्वविद्यालय, विशेषज्ञता और सत्र जोड़ सकते हैं।", es:"Puedes añadir tu universidad, especialización y período.", fr:"Vous pouvez ajouter votre université, spécialisation et semestre.", ur:"آپ اپنی یونیورسٹی، تخصص اور سمسٹر شامل کر سکتے ہیں۔" },
