  "invite.decline": { ar:"رفض", en:"Decline", tr:"Reddet", zh:"拒绝", hi:"अस्वीकार करें", es:"Rechazar", fr:"Refuser", ur:"مسترد کریں" },
  "invite.accept": { ar:"قبول", en:"Accept", tr:"Kabul et", zh:"接受", hi:"स्वीकार करें", es:"Aceptar", fr:"Accepter", ur:"قبول کریں" },
  "invite.emptyTitle": { ar:"لا توجد دعوات معلقة", en:"No pending invitations", tr:"Bekleyen davet yok", zh:"没有待处理的邀请", hi:"कोई लंबित निमंत्रण नहीं", es:"No hay invitaciones pendientes", fr:"Aucune invitation en attente", ur:"کوئی زیر التوا دعوت نہیں" },
  "invite.emptyBody": { ar:"ستظهر هنا الدعوات المطابقة لبريد حسابك.", en:"Invitations matching your account email will appear here.", tr:"Hesap e-postanızla eşleşen davetler burada görünecek.", zh:"与您账户邮箱匹配的邀请将显示在此处。", hi:"आपके खाते के ईमेल से मेल खाने वाले निमंत्रण यहाँ दिखाई देंगे।", es:"Las invitaciones que coincidan con el correo de tu cuenta aparecerán aquí.", fr:"Les invitations correspondant à l'e-mail de votre compte apparaîtront ici.", ur:"آپ کے اکاؤنٹ کے ای میل سے مماثل دعوتیں یہاں ظاہر ہوں گی۔" },

  "search.title": { ar:"ابحث في عملك الأكاديمي", en:"Search your academic work", tr:"Akademik çalışmanızda arayın", zh:"搜索您的学术工作", hi:"अपने शैक्षणिक कार्य में खोजें", es:"Busca en tu trabajo académico", fr:"Recherchez dans votre travail académique", ur:"اپنے تعلیمی کام میں تلاش کریں" },
  "search.description": { ar:"بحث خاضع للصلاحيات في المشاريع، ولأدوار هيئة التدريس في المقررات والتكليفات داخل الـTenant نفسه.", en:"Permission-aware search across projects, and for faculty roles across courses and assignments within the same tenant.", tr:"Aynı kiracı içinde projelerde ve öğretim üyesi rolleri için derslerde ve ödevlerde izin duyarlı arama.", zh:"在同一租户内对项目进行权限感知搜索，以及针对教职角色对课程和作业进行搜索。", hi:"समान टेनेंट के भीतर परियोजनाओं में, और संकाय भूमिकाओं के लिए पाठ्यक्रमों और असाइनमेंट में अनुमति-जागरूक खोज।", es:"Búsqueda con reconocimiento de permisos en proyectos, y para roles docentes en cursos y tareas dentro del mismo inquilino.", fr:"Recherche tenant compte des autorisations dans les projets, et pour les rôles enseignants dans les cours et devoirs au sein du même locataire.", ur:"اسی ٹیننٹ کے اندر پروجیکٹس میں، اور فیکلٹی کرداروں کے لیے کورسز اور اسائنمنٹس میں اجازت سے آگاہ تلاش۔" },
  "search.placeholder": { ar:"اسم مشروع، مقرر، مهارة، تكليف…", en:"Project, course, skill, or assignment name…", tr:"Proje, ders, beceri veya ödev adı…", zh:"项目、课程、技能或作业名称…", hi:"परियोजना, पाठ्यक्रम, कौशल या असाइनमेंट नाम…", es:"Nombre de proyecto, curso, habilidad o tarea…", fr:"Nom de projet, cours, compétence ou devoir…", ur:"پروجیکٹ، کورس، مہارت یا اسائنمنٹ کا نام…" },
  "search.submit": { ar:"بحث", en:"Search", tr:"Ara", zh:"搜索", hi:"खोजें", es:"Buscar", fr:"Rechercher", ur:"تلاش کریں" },
  "search.results": { ar:"النتائج", en:"Results", tr:"Sonuçlar", zh:"结果", hi:"परिणाम", es:"Resultados", fr:"Résultats", ur:"نتائج" },
  "search.emptyTitle": { ar:"لا توجد نتائج مطابقة", en:"No matching results", tr:"Eşleşen sonuç yok", zh:"没有匹配的结果", hi:"कोई मेल खाता परिणाम नहीं", es:"No hay resultados coincidentes", fr:"Aucun résultat correspondant", ur:"کوئی مماثل نتیجہ نہیں" },
  "search.emptyBody": { ar:"جرّب اسم المقرر أو جزءًا من عنوان المشروع.", en:"Try the course name or part of the project title.", tr:"Ders adını veya proje başlığının bir kısmını deneyin.", zh:"尝试课程名称或项目标题的一部分。", hi:"पाठ्यक्रम का नाम या परियोजना शीर्षक का कोई भाग आज़माएँ।", es:"Prueba el nombre del curso o parte del título del proyecto.", fr:"Essayez le nom du cours ou une partie du titre du projet.", ur:"کورس کا نام یا پروجیکٹ کے عنوان کا کوئی حصہ آزمائیں۔" },
  "search.startTitle": { ar:"ابدأ بكلمتين أو أكثر", en:"Start with two or more words", tr:"İki veya daha fazla kelimeyle başlayın", zh:"从两个或更多词开始", hi:"दो या अधिक शब्दों से शुरू करें", es:"Comienza con dos o más palabras", fr:"Commencez avec deux mots ou plus", ur:"دو یا زیادہ الفاظ سے شروع کریں" },
  "search.startBody": { ar:"لن يبحث AcademicOS خارج نطاق بياناتك المسموح بها.", en:"AcademicOS will not search beyond the scope of your permitted data.", tr:"AcademicOS, izin verilen verilerinizin kapsamı dışında arama yapmaz.", zh:"AcademicOS 不会在您获授权的数据范围之外进行搜索。", hi:"AcademicOS आपके अनुमत डेटा के दायरे से बाहर खोज नहीं करेगा।", es:"AcademicOS no buscará más allá del alcance de tus datos permitidos.", fr:"AcademicOS ne cherchera pas au-delà de la portée de vos données autorisées.", ur:"AcademicOS آپ کے مجاز ڈیٹا کے دائرے سے باہر تلاش نہیں کرے گا۔" },
  "search.typeProject": { ar:"مشروع", en:"Project", tr:"Proje", zh:"项目", hi:"परियोजना", es:"Proyecto", fr:"Projet", ur:"پروجیکٹ" },
