  "status.operational": { ar:"تعمل / مُهيّأة", en:"Operational / configured", tr:"Çalışıyor / yapılandırıldı", zh:"运行中／已配置", hi:"चालू / कॉन्फ़िगर किया गया", es:"Operativo / configurado", fr:"Opérationnel / configuré", ur:"فعال / ترتیب شدہ" },
  "status.unavailable": { ar:"غير مُهيّأة أو غير متاحة", en:"Not configured or unavailable", tr:"Yapılandırılmamış veya kullanılamıyor", zh:"未配置或不可用", hi:"कॉन्फ़िगर नहीं या अनुपलब्ध", es:"No configurado o no disponible", fr:"Non configuré ou indisponible", ur:"غیر ترتیب شدہ یا دستیاب نہیں" },
  "status.secretsNote": { ar:"لا تعرض الصفحة مفاتيح أو تفاصيل أسرار المزودين.", en:"This page does not display provider keys or secret details.", tr:"Bu sayfa sağlayıcı anahtarlarını veya gizli bilgileri göstermez.", zh:"此页面不显示提供商的密钥或机密详情。", hi:"यह पृष्ठ प्रदाता की कुंजियाँ या गोपनीय विवरण नहीं दिखाता।", es:"Esta página no muestra claves de proveedores ni detalles secretos.", fr:"Cette page n'affiche pas les clés des fournisseurs ni les détails secrets.", ur:"یہ صفحہ فراہم کنندگان کی کیز یا خفیہ تفصیلات ظاہر نہیں کرتا۔" },

