  "course.joinCodesDesc": { ar:"الرمز الخام يظهر مرة واحدة فقط. المخزن على الخادم هو hash، ويمكن إلغاؤه أو تجديده مع سجل تدقيق.", en:"The raw code appears only once. What is stored on the server is a hash, and it can be revoked or regenerated with an audit log.", tr:"Ham kod yalnızca bir kez görünür. Sunucuda saklanan bir hash'tir ve denetim kaydıyla iptal edilebilir veya yeniden oluşturulabilir.", zh:"原始代码仅显示一次。服务器上存储的是哈希值，可通过审计日志撤销或重新生成。", hi:"कच्चा कोड केवल एक बार दिखता है। सर्वर पर जो संग्रहीत होता है वह एक hash है, और इसे ऑडिट लॉग के साथ रद्द या पुनर्जनित किया जा सकता है।", es:"El código en bruto aparece solo una vez. Lo que se almacena en el servidor es un hash, y puede revocarse o regenerarse con un registro de auditoría.", fr:"Le code brut n'apparaît qu'une seule fois. Ce qui est stocké sur le serveur est un hash, et il peut être révoqué ou régénéré avec un journal d'audit.", ur:"خام کوڈ صرف ایک بار ظاہر ہوتا ہے۔ سرور پر جو محفوظ ہوتا ہے وہ ایک hash ہے، اور اسے آڈٹ لاگ کے ساتھ منسوخ یا دوبارہ تیار کیا جا سکتا ہے۔" },
  "course.noAssignmentForOutcome": { ar:"لا يوجد تكليف يقيس هذا الـOutcome بعد.", en:"No assignment measures this Outcome yet.", tr:"Bu Outcome'u ölçen henüz bir ödev yok.", zh:"尚无作业衡量此 Outcome。", hi:"अभी तक कोई असाइनमेंट इस Outcome को नहीं मापता।", es:"Aún ninguna tarea mide este Outcome.", fr:"Aucun devoir ne mesure encore cet Outcome.", ur:"ابھی تک کوئی اسائنمنٹ اس Outcome کو نہیں ماپتا۔" },
  "course.noAssignments": { ar:"لا توجد تكليفات بعد", en:"No assignments yet", tr:"Henüz ödev yok", zh:"尚无作业", hi:"अभी तक कोई असाइनमेंट नहीं", es:"Aún no hay tareas", fr:"Aucun devoir pour l'instant", ur:"ابھی تک کوئی اسائنمنٹ نہیں" },
  "course.noAssignmentsDesc": { ar:"ابنِ أول Assignment واربطه بالمخرجات والـRubric وسياسة AI.", en:"Build the first Assignment and link it to deliverables, the Rubric, and the AI policy.", tr:"İlk Assignment'ı oluşturun ve çıktılara, Rubric'e ve AI politikasına bağlayın.", zh:"构建第一个 Assignment，并将其与交付物、Rubric 和 AI 政策关联。", hi:"पहला Assignment बनाएं और इसे डिलिवरेबल्स, Rubric और AI नीति से जोड़ें।", es:"Construye la primera Assignment y vincúlala a los entregables, el Rubric y la política de IA.", fr:"Créez le premier Assignment et reliez-le aux livrables, au Rubric et à la politique IA.", ur:"پہلا Assignment بنائیں اور اسے ڈیلیوریبلز، Rubric اور AI پالیسی سے جوڑیں۔" },
  "course.noOutcomes": { ar:"لم تُضف outcomes بعد.", en:"No outcomes added yet.", tr:"Henüz outcome eklenmedi.", zh:"尚未添加 outcomes。", hi:"अभी तक कोई outcomes नहीं जोड़े गए।", es:"Aún no se han añadido outcomes.", fr:"Aucun outcome ajouté pour l'instant.", ur:"ابھی تک کوئی outcomes شامل نہیں کیے گئے۔" },
