  "home.chipNoFakeGrades": { ar:"لا درجات وهمية", en:"No fake grades", tr:"Sahte not yok", zh:"没有虚假成绩", hi:"कोई नकली ग्रेड नहीं", es:"Sin calificaciones falsas", fr:"Pas de fausses notes", ur:"کوئی جعلی گریڈ نہیں" },
