  "plat.prompt.deleteReason": { ar:"سبب الحذف المنطقي (لن يُمسح السجل نهائيًا):", en:"Reason for soft delete (the record will not be permanently erased):", tr:"Mantıksal silme nedeni (kayıt kalıcı olarak silinmeyecek):", zh:"逻辑删除的原因（记录不会被永久删除）：", hi:"सॉफ्ट डिलीट का कारण (रिकॉर्ड स्थायी रूप से नहीं मिटेगा):", es:"Motivo de la eliminación lógica (el registro no se borrará permanentemente):", fr:"Raison de la suppression logique (l'enregistrement ne sera pas effacé définitivement) :", ur:"منطقی حذف کی وجہ (ریکارڈ مستقل طور پر نہیں مٹے گا):" },
