  "share.unlockFailed": { ar:"تعذر فتح المشاركة", en:"Could not open the share", tr:"Paylaşım açılamadı", zh:"无法打开此分享", hi:"शेयर नहीं खोला जा सका", es:"No se pudo abrir el recurso compartido", fr:"Impossible d'ouvrir le partage", ur:"شیئر نہیں کھولا جا سکا" },
