  "team.memberNotice": { ar:"أنت عضو في هذا المشروع. إدارة العضوية محصورة بمالك المشروع.", en:"You are a member of this project. Membership management is limited to the project owner.", tr:"Bu projenin bir üyesisiniz. Üyelik yönetimi proje sahibiyle sınırlıdır.", zh:"您是此项目的成员。成员管理仅限项目所有者。", hi:"आप इस प्रोजेक्ट के सदस्य हैं। सदस्यता प्रबंधन केवल प्रोजेक्ट स्वामी तक सीमित है।", es:"Eres miembro de este proyecto. La gestión de miembros está limitada al propietario del proyecto.", fr:"Vous êtes membre de ce projet. La gestion des membres est réservée au propriétaire du projet.", ur:"آپ اس پروجیکٹ کے رکن ہیں۔ رکنیت کا انتظام صرف پروجیکٹ کے مالک تک محدود ہے۔" },
  "team.membersTitle": { ar:"أعضاء المشروع", en:"Project members", tr:"Proje üyeleri", zh:"项目成员", hi:"प्रोजेक्ट सदस्य", es:"Miembros del proyecto", fr:"Membres du projet", ur:"پروجیکٹ کے ارکان" },
  "team.noContributions": { ar:"لا توجد أحداث كافية لبناء Contribution Evidence بعد.", en:"Not enough events yet to build Contribution Evidence.", tr:"Contribution Evidence oluşturmak için henüz yeterli olay yok.", zh:"尚无足够的事件来构建 Contribution Evidence。", hi:"Contribution Evidence बनाने के लिए अभी पर्याप्त घटनाएँ नहीं हैं।", es:"Aún no hay suficientes eventos para construir Contribution Evidence.", fr:"Pas encore assez d'événements pour construire la Contribution Evidence.", ur:"Contribution Evidence بنانے کے لیے ابھی کافی واقعات نہیں ہیں۔" },
  "team.noPresence": { ar:"لا توجد جلسات نشطة خلال آخر 90 ثانية.", en:"No active sessions in the last 90 seconds.", tr:"Son 90 saniyede etkin oturum yok.", zh:"过去 90 秒内没有活跃会话。", hi:"पिछले 90 सेकंड में कोई सक्रिय सत्र नहीं।", es:"No hay sesiones activas en los últimos 90 segundos.", fr:"Aucune session active au cours des 90 dernières secondes.", ur:"پچھلے 90 سیکنڈ میں کوئی فعال سیشن نہیں۔" },
