  "upload.aiConstraints": { ar:"قيود AI", en:"AI constraints", tr:"AI kısıtlamaları", zh:"AI 限制", hi:"AI बाधाएं", es:"Restricciones de IA", fr:"Contraintes IA", ur:"AI پابندیاں" },
  "upload.aiPolicy": { ar:"سياسة AI", en:"AI policy", tr:"AI politikası", zh:"AI 政策", hi:"AI नीति", es:"Política de IA", fr:"Politique IA", ur:"AI پالیسی" },
  "upload.buildWorkspace": { ar:"بناء مساحة العمل", en:"Build workspace", tr:"Çalışma alanı oluştur", zh:"构建工作区", hi:"वर्कस्पेस बनाएं", es:"Construir espacio de trabajo", fr:"Créer l'espace de travail", ur:"ورک اسپیس بنائیں" },
  "upload.cameraHint": { ar:"على الهاتف يمكنك تصوير ورقة التكليف مباشرة؛ الصورة تدخل نفس مسار التحليل ولا يوجد OCR وهمي في الواجهة.", en:"On phone you can photograph the assignment sheet directly; the image enters the same analysis path and there is no fake OCR in the interface.", tr:"Telefonda ödev kağıdını doğrudan fotoğraflayabilirsiniz; görüntü aynı analiz yoluna girer ve arayüzde sahte OCR yoktur.", zh:"在手机上您可以直接拍摄作业纸；图片进入相同的分析流程，界面中没有虚假的 OCR。", hi:"फ़ोन पर आप असाइनमेंट शीट की सीधे तस्वीर ले सकते हैं; छवि उसी विश्लेषण पथ में जाती है और इंटरफ़ेस में कोई नकली OCR नहीं है।", es:"En el teléfono puedes fotografiar la hoja de la tarea directamente; la imagen entra en la misma ruta de análisis y no hay OCR falso en la interfaz.", fr:"Sur téléphone, vous pouvez photographier directement la feuille du devoir ; l'image suit le même parcours d'analyse et il n'y a pas de faux OCR dans l'interface.", ur:"فون پر آپ اسائنمنٹ شیٹ کی براہِ راست تصویر لے سکتے ہیں؛ تصویر اسی تجزیاتی راستے میں جاتی ہے اور انٹرفیس میں کوئی فرضی OCR نہیں۔" },
  "upload.capturePhoto": { ar:"التقاط صورة", en:"Capture photo", tr:"Fotoğraf çek", zh:"拍摄照片", hi:"फ़ोटो लें", es:"Tomar foto", fr:"Prendre une photo", ur:"تصویر لیں" },
  "upload.clipboardDenied": { ar:"لم يسمح المتصفح بقراءة الحافظة. استخدم اللصق داخل الحقل.", en:"The browser blocked clipboard access. Paste directly into the field.", tr:"Tarayıcı pano erişimine izin vermedi. Doğrudan alana yapıştırın.", zh:"浏览器阻止了剪贴板访问。请直接粘贴到字段中。", hi:"ब्राउज़र ने क्लिपबोर्ड एक्सेस रोक दिया। सीधे फ़ील्ड में पेस्ट करें।", es:"El navegador bloqueó el acceso al portapapeles. Pega directamente en el campo.", fr:"Le navigateur a bloqué l'accès au presse-papiers. Collez directement dans le champ.", ur:"براؤزر نے کلپ بورڈ تک رسائی روک دی۔ براہِ راست فیلڈ میں پیسٹ کریں۔" },
