  "viva.answerPlaceholder": { ar:"اكتب إجابتك…", en:"Write your answer…", tr:"Yanıtınızı yazın…", zh:"写下你的回答…", hi:"अपना उत्तर लिखें…", es:"Escribe tu respuesta…", fr:"Écrivez votre réponse…", ur:"اپنا جواب لکھیں…" },
  "viva.finishBtn": { ar:"إنهاء وتسجيل Proof of Learning", en:"Finish and record Proof of Learning", tr:"Bitir ve Proof of Learning'i kaydet", zh:"完成并记录 Proof of Learning", hi:"समाप्त करें और Proof of Learning दर्ज करें", es:"Finalizar y registrar Proof of Learning", fr:"Terminer et enregistrer Proof of Learning", ur:"ختم کریں اور Proof of Learning ریکارڈ کریں" },
  "viva.introDesc": { ar:"الأسئلة تُبنى من Project DNA والـRubric والمخاطر الحالية. إجاباتك تُحفظ كدليل تعلم قابل للمراجعة؛ لا يحوّلها النظام إلى حكم آلي على أصالة الطالب.", en:"Questions are built from the Project DNA, the Rubric and current risks. Your answers are saved as reviewable learning evidence; the system does not turn them into an automated judgment of the student's authenticity.", tr:"Sorular Project DNA'dan, Rubric'ten ve mevcut risklerden oluşturulur. Yanıtlarınız incelenebilir öğrenme kanıtı olarak kaydedilir; sistem bunları öğrencinin özgünlüğü hakkında otomatik bir yargıya dönüştürmez.", zh:"问题基于 Project DNA、Rubric 和当前风险生成。你的回答会作为可复核的学习证据保存；系统不会将其转化为对学生真实性的自动判定。", hi:"प्रश्न Project DNA, Rubric और वर्तमान जोखिमों से बनाए जाते हैं। आपके उत्तर समीक्षा-योग्य अधिगम प्रमाण के रूप में सहेजे जाते हैं; सिस्टम उन्हें छात्र की प्रामाणिकता पर स्वचालित निर्णय में नहीं बदलता।", es:"Las preguntas se construyen a partir del Project DNA, el Rubric y los riesgos actuales. Tus respuestas se guardan como evidencia de aprendizaje revisable; el sistema no las convierte en un juicio automático sobre la autenticidad del estudiante.", fr:"Les questions sont construites à partir du Project DNA, du Rubric et des risques actuels. Vos réponses sont enregistrées comme preuve d'apprentissage vérifiable ; le système ne les transforme pas en un jugement automatique sur l'authenticité de l'étudiant.", ur:"سوالات Project DNA، Rubric اور موجودہ خطرات سے بنائے جاتے ہیں۔ آپ کے جوابات قابلِ جائزہ سیکھنے کے ثبوت کے طور پر محفوظ ہوتے ہیں؛ نظام انہیں طالب علم کی اصلیت پر خودکار فیصلے میں تبدیل نہیں کرتا۔" },
  "viva.introTitle": { ar:"اختبر فهمك، لا “نسبة الـAI”", en:"Test your understanding, not an “AI percentage”", tr:"Bir “AI yüzdesini” değil, anlayışınızı test edin", zh:"检验你的理解，而不是“AI 百分比”", hi:"अपनी समझ जाँचें, कोई “AI प्रतिशत” नहीं", es:"Pon a prueba tu comprensión, no un “porcentaje de IA”", fr:"Testez votre compréhension, pas un “pourcentage d'IA”", ur:"اپنی سمجھ کو جانچیں، کوئی “AI فیصد” نہیں" },
  "viva.learningDesc": { ar:"أدلة موثقة من جلسات المناقشة والقرارات البشرية.", en:"Documented evidence from viva sessions and human decisions.", tr:"Viva oturumlarından ve insan kararlarından belgelenmiş kanıtlar.", zh:"来自答辩环节与人为决策的有据可查的证据。", hi:"विवा सत्रों और मानवीय निर्णयों से प्रलेखित प्रमाण।", es:"Evidencia documentada de las sesiones de viva y de decisiones humanas.", fr:"Preuves documentées issues des sessions de viva et des décisions humaines.", ur:"وائیوا سیشنز اور انسانی فیصلوں سے مستند شواہد۔" },
  "viva.learningEmpty": { ar:"لا يوجد دليل تعلم مسجل بعد.", en:"No learning evidence recorded yet.", tr:"Henüz kayıtlı öğrenme kanıtı yok.", zh:"尚未记录任何学习证据。", hi:"अभी तक कोई अधिगम प्रमाण दर्ज नहीं किया गया।", es:"Aún no se ha registrado evidencia de aprendizaje.", fr:"Aucune preuve d'apprentissage enregistrée pour l'instant.", ur:"ابھی تک کوئی سیکھنے کا ثبوت ریکارڈ نہیں ہوا۔" },
  "viva.liveTitle": { ar:"أجب بصوتك الفكري أنت", en:"Answer in your own intellectual voice", tr:"Kendi entelektüel sesinizle yanıtlayın", zh:"用你自己的思想之声作答", hi:"अपनी बौद्धिक आवाज़ में उत्तर दें", es:"Responde con tu propia voz intelectual", fr:"Répondez avec votre propre voix intellectuelle", ur:"اپنی فکری آواز میں جواب دیں" },
